{
    size_t i, j, k;
    unsigned char tmp;
    unsigned char idx[8];

    if (in_pos >= in_len)
        return -1;

    for (i = 0; i < 8; i++)
        idx[i] = i;

    for (i = 8; i > 0; i--) {
        k = in_pos % i;
        tmp = idx[i - 1];
        idx[i - 1] = idx[k];
        idx[k] = tmp;
        in_pos /= i;
    }

    for (i = 0; i < in_len; i += 8) {
        for (j = 0; j < 8; j++)
            out[i + j] = in[i + idx[j]];
    }

    for (i = in_len; i < out_len; i++)
        out[i] = in[i];

    return out_len;
}

